CREATE OR REPLACE FUNCTION public.pm_b1_pursuit(_project uuid, _preview boolean DEFAULT false) RETURNS TABLE(project_id uuid, resource_id uuid, hours numeric, snapshot_cost numeric, hours_without_snapshot numeric) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.is_psa_staff() OR _project IS NULL THEN RETURN; END IF; IF NOT EXISTS(SELECT 1 FROM public.pm_projects p WHERE p.id=_project AND NOT p.finance_only AND (public.has_role(auth.uid(),'admin') OR public.pm_can_view_projects(auth.uid()) OR public.pm_has_assigned_access(auth.uid(),p.id))) THEN RETURN; END IF; IF NOT (_preview OR public.pm_project_b1_active()) THEN RETURN; END IF; IF NOT public.pm_project_area_proposed(_project,'budget_cost',auth.uid()) THEN RETURN QUERY SELECT _project,NULL::uuid,NULL::numeric,NULL::numeric,NULL::numeric; RETURN; END IF; RETURN QUERY SELECT p.id,r.id,sum(e.hours),sum(CASE WHEN e.cost_rate_snapshot IS NOT NULL THEN e.hours*e.cost_rate_snapshot ELSE 0 END),sum(CASE WHEN e.cost_rate_snapshot IS NULL THEN e.hours ELSE 0 END) FROM public.pm_projects p JOIN public.pm_time_entries e ON e.opportunity_id=p.opportunity_id AND e.entry_type='internal' AND e.internal_category='Pursuit' LEFT JOIN auth.users u ON u.id=e.user_id LEFT JOIN LATERAL(SELECT r0.id FROM public.pm_resources r0 WHERE r0.email=u.email OR (r0.collaborator_id IS NOT NULL AND public.get_user_id_for_collaborator(r0.collaborator_id)=e.user_id) ORDER BY r0.id LIMIT 1) r ON true WHERE p.id=_project AND p.opportunity_id IS NOT NULL GROUP BY p.id,r.id; END $$; REVOKE ALL ON FUNCTION public.pm_b1_pursuit(uuid,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.pm_b1_pursuit(uuid,boolean) TO authenticated,service_role; COMMENT ON FUNCTION public.pm_b1_pursuit(uuid,boolean) IS 'Pursuit belongs to Budget. Caller/project-scoped B1 totals preserve saved snapshots and missing-snapshot hours; denied cost is null, not a fabricated zero. Read-only preview applies proposed areas without changing either gate.';